#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t algorithm_histogram(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        // Reset histogram array x[256] to 0.0
        #if defined(__riscv_vector)
        size_t vl = __riscv_vsetvl_e32m1(256);
        vfloat32m1_t zero_vec = __riscv_vfmv_v_f_f32m1(0.0f, vl);
        __riscv_vse32_f(x, zero_vec, vl);
        #else
        for (Index_type i = 0; i < 256; ++i) x[i] = 0.0;
        #endif

        // Accumulate histogram: x[idx_list[i]] += 1.0
        // Note: Vectorizing random scatter-add is not safe/standard in RVV without atomics or specific extensions.
        // We keep this loop scalar to ensure correctness and match original behavior exactly.
        for (Index_type i = 0; i < LEN_1D; ++i) {
            x[idx_list[i]] += 1.0;
        }

        dummy(x, NULL, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

