real_t algorithm_memcpy(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        size_t i = 0;
        // Use a larger LMUL (m8) to maximize throughput if supported, falling back to m1 logic via vsetvl_e32m8
        // We calculate the total length once.
        size_t len = LEN_1D;

        // Set VL for maximum possible vector length with m8 grouping for float32
        size_t vl = __riscv_vsetvl_e32m8(len);

        while (i < len) {
            // Load and store using m8 width for better bandwidth utilization
            vfloat32m8_t vx = __riscv_vle32_v_f32m8(&x[i], vl);
            __riscv_vse32_v_f32m8(&y[i], vx, vl);

            i += vl;
            if (i < len) {
                vl = __riscv_vsetvl_e32m8(len - i);
            }
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            y[i] = x[i];
        }
#endif
        dummy(x, y, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

