real_t algorithm_memset(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t val = 1.42;
    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        size_t i = 0;
        while (i < LEN_1D) {
            size_t remaining = LEN_1D - i;
            // Set vector length for the current chunk
            size_t vl = __riscv_vsetvl_e32m1(remaining);

            // Broadcast scalar 'val' to a vector of floats using vfmv.v.f
            vfloat32m1_t v_broadcast = __riscv_vfmv_v_f(vl, val);

            // Store the vector to memory starting at x + i
            __riscv_vse32_v(x + i, v_broadcast, vl);

            i += vl;
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            x[i] = val;
        }
#endif
        dummy(x, NULL, NULL, NULL, NULL, val);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t algorithm_reduce_sum(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t acc = 0.0;

#if defined(__riscv_vector)
    // Determine vector length for the inner loop
    size_t vl = __riscv_vsetvl_e32m1(LEN_1D);

    for (int nl = 0; nl < iterations; nl++) {
        real_t s = 0.0;

        // Vectorized sum over x array
        vfloat32m1_t v_acc = __riscv_vfmv_v_f_f32m1(0.0f, vl);
        size_t i = 0;

        // Process full vector blocks
        while (i + vl <= LEN_1D) {
            vfloat32m1_t v_x = __riscv_vle32_v_f32m1(&x[i], vl);
            v_acc = __riscv_vfadd_vv_f32m1(v_acc, v_x, vl);
            i += vl;
        }

        // Reduce vector accumulator to scalar using fold reduce
        if (vl > 0) {
            s = __riscv_vfredosum_vs_f32m1(v_acc, 0.0f, vl);
        }

        // Handle remaining elements with scalar loop
        for (; i < LEN_1D; ++i) {
            s += x[i];
        }

        acc += s;
        dummy(x, NULL, NULL, NULL, NULL, s);
    }
#else
    for (int nl = 0; nl < iterations; nl++) {
        real_t s = 0.0;
        for (Index_type i = 0; i < LEN_1D; ++i) s += x[i];
        acc += s;
        dummy(x, NULL, NULL, NULL, NULL, s);
    }
#endif

    y[0] = acc / ((real_t)(iterations) * (real_t)(LEN_1D));

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

