real_t algorithm_scan(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        real_t scan_var = 0.0;

#if defined(__riscv_vector)
        size_t i = 0;

        // Process in chunks of vector length
        while (i < LEN_1D) {
            size_t remaining = LEN_1D - i;
            size_t current_vl = __riscv_vsetvl_e32m1(remaining);

            // Load x[i] to x[i+current_vl-1]
            vfloat32m1_t vx = __riscv_vle32_v_f32m1((const float*)&x[i], current_vl);

            // Add scan_var to each element for y: vy = vx + scan_var
            vfloat32m1_t vy = __riscv_vfadd_vf_f32m1(vx, scan_var, current_vl);

            // Store y
            __riscv_vse32_v_f32m1((float*)&y[i], vy, current_vl);

            // Compute sum of vx elements and add to scan_var
            // Use vfredusum_vs for floating point reduction sum with scalar accumulator
