real_t apps_del_dot_vec_2d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t half = 0.5f, ptiny = 1.0e-2f;

#if defined(__riscv_vector)
    size_t n = APPS_N1D;

    // Load base pointers for vector operations
    const real_t *x1_p = apps_x1;
    const real_t *x2_p = apps_x2;
    const real_t *x3_p = apps_x3;
    const real_t *x4_p = apps_x4;
    const real_t *y1_p = apps_y1;
    const real_t *y2_p = apps_y2;
    const real_t *y3_p = apps_y3;
    const real_t *y4_p = apps_y4;
    const real_t *fx1_p = apps_fx1;
    const real_t *fx2_p = apps_fx2;
    const real_t *fx3_p = apps_fx3;
    const real_t *fx4_p = apps_fx4;
    const real_t *fy1_p = apps_fy1;
    const real_t *fy2_p = apps_fy2;
    const real_t *fy3_p = apps_fy3;
    const real_t *fy4_p = apps_fy4;
    real_t *div_p = apps_div;

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        size_t i = 0;
        while (i < n) {
            size_t vl_actual = __riscv_vsetvl_e32m1(n - i);

            // Create scalar-to-vector constants using correct intrinsic name
            vfloat32m1_t vhalf = __riscv_vfmv_f_v(half, vl_actual);
            vfloat32m1_t vptiny = __riscv_vfmv_f_v(ptiny, vl_actual);
            vfloat32m1_t vone = __riscv_vfmv_f_v(1.0f, vl_actual);
            vfloat32m1_t vtwo = __riscv_vfmv_f_v(2.0f, vl_actual);

            // Load vectors
            vfloat32m1_t vx1 = __riscv_vle32_v_f32m1(x1_p + i, vl_actual);
            vfloat32m1_t vx2 = __riscv_vle32_v_f32m1(x2_p + i, vl_actual);
            vfloat32m1_t vx3 = __riscv_vle32_v_f32m1(x3_p + i, vl_actual);
            vfloat32m1_t vx4 = __riscv_vle32_v_f32m1(x4_p + i, vl_actual);

            vfloat32m1_t vy1 = __riscv_vle32_v_f32m1(y1_p + i, vl_actual);
            vfloat32m1_t vy2 = __riscv_vle32_v_f32m1(y2_p + i, vl_actual);
            vfloat32m1_t vy3 = __riscv_vle32_v_f32m1(y3_p + i, vl_actual);
            vfloat32m1_t vy4 = __riscv_vle32_v_f32m1(y4_p + i, vl_actual);

            vfloat32m1_t vfx1 = __riscv_vle32_v_f32m1(fx1_p + i, vl_actual);
            vfloat32m1_t vfx2 = __riscv_vle32_v_f32m1(fx2_p + i, vl_actual);
            vfloat32m1_t vfx3 = __riscv_vle32_v_f32m1(fx3_p + i, vl_actual);
            vfloat32m1_t vfx4 = __riscv_vle32_v_f32m1(fx4_p + i, vl_actual);

            vfloat32m1_t vfy1 = __riscv_vle32_v_f32m1(fy1_p + i, vl_actual);
            vfloat32m1_t vfy2 = __riscv_vle32_v_f32m1(fy2_p + i, vl_actual);
            vfloat32m1_t vfy3 = __riscv_vle32_v_f32m1(fy3_p + i, vl_actual);
            vfloat32m1_t vfy4 = __riscv_vle32_v_f32m1(fy4_p + i, vl_actual);

            // Compute xi, xj, yi, yj
            // xi = half * (x1 + x2 - x3 - x4)
            vfloat32m1_t vxi = __riscv_vfmul_vf(
                __riscv_vfsub_vv(
                    __riscv_vfadd_vv(vx1, vx2), 
                    __riscv_vfadd_vv(vx3, vx4)), 
                half, vl_actual);

            // xj = half * (x2 + x3 - x4 - x1)
            vfloat32m1_t vxj = __riscv_vfmul_vf(
                __riscv_vfsub_vv(
                    __riscv_vfadd_vv(vx2, vx3), 
                    __riscv_vfadd_vv(vx4, vx1)), 
                half, vl_actual);

            // yi = half * (y1 + y2 - y3 - y4)
            vfloat32m1_t vyi = __riscv_vfmul_vf(
                __riscv_vfsub_vv(
                    __riscv_vfadd_vv(vy1, vy2), 
                    __riscv_vfadd_vv(vy3, vy4)), 
                half, vl_actual);

            // yj = half * (y2 + y3 - y4 - y1)
            vfloat32m1_t vyj = __riscv_vfmul_vf(
                __riscv_vfsub_vv(
                    __riscv_vfadd_vv(vy2, vy3), 
                    __riscv_vfadd_vv(vy4, vy1)), 
                half, vl_actual);

            // Compute fxi, fxj, fyi, fyj
            vfloat32m1_t vfxi = __riscv_vfmul_vf(
                __riscv_vfsub_vv(
                    __riscv_vfadd_vv(vfx1, vfx2), 
                    __riscv_vfadd_vv(vfx3, vfx4)), 
                half, vl_actual);

            vfloat32m1_t vfxj = __riscv_vfmul_vf(
                __riscv_vfsub_vv(
                    __riscv_vfadd_vv(vfx2, vfx3), 
                    __riscv_vfadd_vv(vfx4, vfx1)), 
                half, vl_actual);

            vfloat32m1_t vfyi = __riscv_vfmul_vf(
                __riscv_vfsub_vv(
                    __riscv_vfadd_vv(vfy1, vfy2), 
                    __riscv_vfadd_vv(vfy3, vfy4)), 
                half, vl_actual);

            vfloat32m1_t vfyj = __riscv_vfmul_vf(
                __riscv_vfsub_vv(
                    __riscv_vfadd_vv(vfy2, vfy3), 
                    __riscv_vfadd_vv(vfy4, vfy1)), 
                half, vl_actual);

            // Compute rarea = 1.0f / (xi * yj - xj * yi + ptiny)
            vfloat32m1_t vdenom = __riscv_vfadd_vv(
                __riscv_vfsub_vv(
                    __riscv_vfmul_vv(vxi, vyj),
                    __riscv_vfmul_vv(vxj, vyi)
                ),
                vptiny, vl_actual
            );

            // Reciprocal approximation and refinement
            vfloat32m1_t vrarea = __riscv_vfrec7_v(vdenom, vl_actual);
            // Newton-Raphson refinement: x_new = x * (2 - d * x)
            vrarea = __riscv_vfnmsub_vff(vrarea, __riscv_vfmul_vv(vrarea, vdenom), vtwo, vl_actual);

            // Compute dfxdx = rarea * (fxi * yj - fxj * yi)
            vfloat32m1_t vdfxdx = __riscv_vfmul_vv(vrarea, 
                __riscv_vfsub_vv(
                    __riscv_vfmul_vv(vfxi, vyj),
                    __riscv_vfmul_vv(vfxj, vyi)
                ), vl_actual);

            // Compute dfydy = rarea * (fyj * xi - fyi * xj)
            vfloat32m1_t vdfydy = __riscv_vfmul_vv(vrarea,
                __riscv_vfsub_vv(
                    __riscv_vfmul_vv(vfyj, vxi),
                    __riscv_vfmul_vv(vfyi, vxj)
                ), vl_actual);

            // Compute affine = sum(fy) / sum(y)
            vfloat32m1_t vsum_fy = __riscv_vfadd_vv(
                __riscv_vfadd_vv(vfy1, vfy2),
                __riscv_vfadd_vv(vfy3, vfy4), vl_actual
            );
            vfloat32m1_t vsum_y = __riscv_vfadd_vv(
                __riscv_vfadd_vv(vy1, vy2),
                __riscv_vfadd_vv(vy3, vy4), vl_actual
            );
            vfloat32m1_t vaffine = __riscv_vfdiv_vv(vsum_fy, vsum_y, vl_actual);

            // Final result: dfxdx + dfydy + affine
            vfloat32m1_t vresult = __riscv_vfadd_vv(
                __riscv_vfadd_vv(vdfxdx, vdfydy),
                vaffine, vl_actual
            );

            // Store result
            __riscv_vse32_v_f32m1(div_p + i, vresult, vl_actual);

            i += vl_actual;
        }
        dummy(apps_div, NULL, NULL, NULL, NULL, ptiny);
    }
#else
    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t xi  = half * ( apps_x1[i]  + apps_x2[i]  - apps_x3[i]  - apps_x4[i]  );
            real_t xj  = half * ( apps_x2[i]  + apps_x3[i]  - apps_x4[i]  - apps_x1[i]  );
            real_t yi  = half * ( apps_y1[i]  + apps_y2[i]  - apps_y3[i]  - apps_y4[i]  );
            real_t yj  = half * ( apps_y2[i]  + apps_y3[i]  - apps_y4[i]  - apps_y1[i]  );
            real_t fxi = half * ( apps_fx1[i] + apps_fx2[i] - apps_fx3[i] - apps_fx4[i] );
            real_t fxj = half * ( apps_fx2[i] + apps_fx3[i] - apps_fx4[i] - apps_fx1[i] );
            real_t fyi = half * ( apps_fy1[i] + apps_fy2[i] - apps_fy3[i] - apps_fy4[i] );
            real_t fyj = half * ( apps_fy2[i] + apps_fy3[i] - apps_fy4[i] - apps_fy1[i] );
            real_t rarea = 1.0f / ( xi * yj - xj * yi + ptiny );
            real_t dfxdx  = rarea * ( fxi * yj - fxj * yi );
            real_t dfydy  = rarea * ( fyj * xi - fyi * xj );
            real_t affine = ( apps_fy1[i] + apps_fy2[i] + apps_fy3[i] + apps_fy4[i] ) /
                            ( apps_y1[i]  + apps_y2[i]  + apps_y3[i]  + apps_y4[i]  );
            apps_div[i] = dfxdx + dfydy + affine;
        }
        dummy(apps_div, NULL, NULL, NULL, NULL, ptiny);
    }
#endif

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

