real_t apps_pressure(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t cls = 1.0f, p_cut = 1.0e-7f, pmin = 0.0f, eosvmax = 1.0e9f;

    size_t loop_count = iterations / 4 + 1;

    for (int nl = 0; nl < loop_count; nl++) {
        // Vectorized first loop: apps_bvc[i] = cls * (apps_compression[i] + 1.0f);
        #if defined(__riscv_vector)
        size_t i = 0;
        while (i < APPS_N1D) {
            size_t vl = __riscv_vsetvl_e32m1(APPS_N1D - i);
            vfloat32m1_t v_comp = __riscv_vle32_v_f32m1(&apps_compression[i], vl);
            vfloat32m1_t v_one = __riscv_vfmv_v_f(1.0f, vl);
            vfloat32m1_t v_sum = __riscv_vfadd_vv(v_comp, v_one, vl);
            vfloat32m1_t v_cls_vec = __riscv_vfmv_v_f(cls, vl);
            vfloat32m1_t v_bvc = __riscv_vfmul_vv(v_sum, v_cls_vec, vl);
            __riscv_vse32_v_f32m1(&apps_bvc[i], v_bvc, vl);
            i += vl;
        }
        #else
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_bvc[i] = cls * (apps_compression[i] + 1.0f);
        }
        #endif

        // Vectorized second loop with conditional logic
        #if defined(__riscv_vector)
        i = 0;
        while (i < APPS_N1D) {
            size_t vl = __riscv_vsetvl_e32m1(APPS_N1D - i);

            // Load data
            vfloat32m1_t v_bvc = __riscv_vle32_v_f32m1(&apps_bvc[i], vl);
            vfloat32m1_t v_e_old = __riscv_vle32_v_f32m1(&apps_e_old[i], vl);
            vfloat32m1_t v_vnewc = __riscv_vle32_v_f32m1(&apps_vnewc[i], vl);

            // Calculate p = bvc * e_old
            vfloat32m1_t v_p = __riscv_vfmul_vv(v_bvc, v_e_old, vl);

            // Condition 1: if ABS(p) < p_cut then p = 0.0f
            vbool32_t mask_abs = __riscv_vmflt_vf_f32m1_b32(__riscv_vfabs_v_f32m1(v_p, vl), p_cut, vl);
            vfloat32m1_t v_zero = __riscv_vfmv_v_f(0.0f, vl);
            vfloat32m1_t v_p_cond1 = __riscv_vmerge_vm(v_zero, v_p, mask_abs, vl);

            // Condition 2: if vnewc >= eosvmax then p = 0.0f
            vbool32_t mask_ge = __riscv_vmgge_vf_f32m1_b32(v_vnewc, eosvmax, vl);
            vfloat32m1_t v_p_cond2 = __riscv_vmerge_vm(v_zero, v_p_cond1, mask_ge, vl);

            // Condition 3: if p < pmin then p = pmin
            vbool32_t mask_lt = __riscv_vmlt_vf_f32m1_b32(v_p_cond2, pmin, vl);
            vfloat32m1_t v_pmin_vec = __riscv_vfmv_v_f(pmin, vl);
            vfloat32m1_t v_p_final = __riscv_vmerge_vm(v_pmin_vec, v_p_cond2, mask_lt, vl);

            // Store result
            __riscv_vse32_v_f32m1(&apps_p_new[i], v_p_final, vl);

            i += vl;
        }
        #else
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t p = apps_bvc[i] * apps_e_old[i];
            if (ABS(p) < p_cut)         p = 0.0f;
            if (apps_vnewc[i] >= eosvmax) p = 0.0f;
            if (p < pmin)               p = pmin;
            apps_p_new[i] = p;
        }
        #endif

        dummy(apps_p_new, apps_bvc, NULL, NULL, NULL, p_cut);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

