        vfloat32m1_t vy0 = __riscv_vle32_v_f32m1(apps_y0, vl);
        vfloat32m1_t vy5 = __riscv_vle32_v_f32m1(apps_y5, vl);
        vfloat32m1_t vy6 = __riscv_vle32_v_f32m1(apps_y6, vl);

