        vfloat32m1_t vz4 = __riscv_vle32_v_f32m1(apps_z4, vl);
        vfloat32m1_t vz3 = __riscv_vle32_v_f32m1(apps_z3, vl);
        vfloat32m1_t vz0 = __riscv_vle32_v_f32m1(apps_z0, vl);
        vfloat32m1_t vz5 = __riscv_vle32_v_f32m1(apps_z5, vl);
        vfloat32m1_t vz6 = __riscv_vle32_v_f32m1(apps_z6, vl);

