        vfloat32m1_t y74 = __riscv_vfsub_vv_f32m1(vl, vy7, vy4);
        vfloat32m1_t y30 = __riscv_vfsub_vv_f32m1(vl, vy3, vy0);
        vfloat32m1_t y50 = __riscv_vfsub_vv_f32m1(vl, vy5, vy0);
        vfloat32m1_t y60 = __riscv_vfsub_vv_f32m1(vl, vy6, vy0);

        vfloat32m1_t z71 = __riscv_vfsub_vv_f32m1(vl, vz7, vz1);
        vfloat32m1_t z72 = __riscv_vfsub_vv_f32m1(vl, vz7, vz2);
        vfloat32m1_t z74 = __riscv_vfsub_vv_f32m1(vl, vz7, vz4);
        vfloat32m1_t z30 = __riscv_vfsub_vv_f32m1(vl, vz3, vz0);
        vfloat32m1_t z50 = __riscv_vfsub_vv_f32m1(vl, vz5, vz0);
        vfloat32m1_t z60 = __riscv_vfsub_vv_f32m1(vl, vz6, vz0);

        // First term: xps*cyz + yps*czx + zps*cxy
        vfloat32m1_t xps = __riscv_vfadd_vv_f32m1(vl, x71, x60);
        vfloat32m1_t yps = __riscv_vfadd_vv_f32m1(vl, y71, y60);
        vfloat32m1_t zps = __riscv_vfadd_vv_f32m1(vl, z71, z60);

        vfloat32m1_t cyz = __riscv_vfmul_vv_f32m1(vl, y72, z30);
        cyz = __riscv_vfnmsub_vv_f32m1(vl, cyz, z72, y30);

        vfloat32m1_t czx = __riscv_vfmul_vv_f32m1(vl, z72, x30);
        czx = __riscv_vfnmsub_vv_f32m1(vl, czx, x72, z30);

        vfloat32m1_t cxy = __riscv_vfmul_vv_f32m1(vl, x72, y30);
        cxy = __riscv_vfnmsub_vv_f32m1(vl, cxy, y72, x30);

