        czx = __riscv_vfmul_vv_f32m1(vl, z74, x60);
        czx = __riscv_vfnmsub_vv_f32m1(vl, czx, x74, z60);

        cxy = __riscv_vfmul_vv_f32m1(vl, x74, y60);
        cxy = __riscv_vfnmsub_vv_f32m1(vl, cxy, y74, x60);

        v = __riscv_vfmacc_vv_f32m1(vl, v, xps, cyz);
        v = __riscv_vfmacc_vv_f32m1(vl, v, yps, czx);
        v = __riscv_vfmacc_vv_f32m1(vl, v, zps, cxy);

