        yps = __riscv_vfadd_vv_f32m1(vl, y74, y30);
        zps = __riscv_vfadd_vv_f32m1(vl, z74, z30);

        cyz = __riscv_vfmul_vv_f32m1(vl, y71, z50);
        cyz = __riscv_vfnmsub_vv_f32m1(vl, cyz, z71, y50);

        czx = __riscv_vfmul_vv_f32m1(vl, z71, x50);
        czx = __riscv_vfnmsub_vv_f32m1(vl, czx, x71, z50);

        cxy = __riscv_vfmul_vv_f32m1(vl, x71, y50);
        cxy = __riscv_vfnmsub_vv_f32m1(vl, cxy, y71, x50);

        v = __riscv_vfmacc_vv_f32m1(vl, v, xps, cyz);
        v = __riscv_vfmacc_vv_f32m1(vl, v, yps, czx);
        v = __riscv_vfmacc_vv_f32m1(vl, v, zps, cxy);

        // Multiply by vnormq and store
        v = __riscv_vfmul_vf_f32m1(vl, v, vnormq);
        __riscv_vse32_v_f32m1(apps_vol, v, vl);

        dummy(apps_vol, NULL, NULL, NULL, NULL, vnormq);
    }
#else
    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        for (Index_type i = 0; i < APPS_N1D; ++i) {
