real_t basic_if_quad(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
        #if defined(__riscv_vector)
        size_t vl = __riscv_vsetvl_e32m1(LEN_1D);

        // Load vectors using correct intrinsic names
        vfloat32m1_t va = __riscv_vle32_v_f32(a, vl);
        vfloat32m1_t vb = __riscv_vle32_v_f32(b, vl);
        vfloat32m1_t vc = __riscv_vle32_v_f32(c, vl);

        // s = b[i]*b[i] - 4.0*a[i]*c[i]
        vfloat32m1_t vb_sq = __riscv_vfmul_vv_f32(vb, vb, vl);
        vfloat32m1_t ac_prod = __riscv_vfmul_vv_f32(va, vc, vl);
        vfloat32m1_t four_ac = __riscv_vfmul_vf_f32(ac_prod, 4.0f, vl);
        vfloat32m1_t vs = __riscv_vfsub_vv_f32(vb_sq, four_ac, vl);

        // Mask: s >= 0
        vbool8_t vm = __riscv_vmfge_vf_f32_m(vs, 0.0f, vl);

        // Compute sqrt(s) where s >= 0
        vfloat32m1_t vs_sqrt = __riscv_vsqrt_v_f32(vs, vl);

        // Prepare denominator: 2.0 * a[i]
        vfloat32m1_t denom = __riscv_vfmul_vf_f32(va, 2.0f, vl);

        // Numerators: -b + s and -b - s
        vfloat32m1_t neg_b = __riscv_vfneg_v_f32(vb, vl);
        vfloat32m1_t num1 = __riscv_vfadd_vv_f32(neg_b, vs_sqrt, vl); // (-b + s)
        vfloat32m1_t num2 = __riscv_vfsub_vv_f32(neg_b, vs_sqrt, vl); // (-b - s)

        // Results for true branch
        vfloat32m1_t out1_true = __riscv_vfdiv_vv_f32(num2, denom, vl);
        vfloat32m1_t out2_true = __riscv_vfdiv_vv_f32(num1, denom, vl);

        // Results for false branch (0.0)
        vfloat32m1_t out1_false = __riscv_vmv_v_x_f32(0, vl);
        vfloat32m1_t out2_false = __riscv_vmv_v_x_f32(0, vl);

        // Merge based on mask
        vfloat32m1_t vout1 = __riscv_vmerge_vm_f32(out1_false, out1_true, vm, vl);
        vfloat32m1_t vout2 = __riscv_vmerge_vm_f32(out2_false, out2_true, vm, vl);

        // Store results
        __riscv_vse32_v_f32(out1, vout1, vl);
        __riscv_vse32_v_f32(out2, vout2, vl);
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t s = b[i]*b[i] - 4.0*a[i]*c[i];
            if (s >= 0) {
                s = sqrtf(s);
                out2[i] = (-b[i]+s)/(2.0*a[i]);
                out1[i] = (-b[i]-s)/(2.0*a[i]);
            } else {
                out2[i] = 0.0;
                out1[i] = 0.0;
            }
        }
        #endif
        dummy(out1, out2, a, b, c, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

