real_t basic_indexlist(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type len = 0;
    for (int nl = 0; nl < iterations / 8 + 1; nl++) {
        Index_type count = 0;

#if defined(__riscv_vector)
        size_t vl;
        vbool32_t mask;
        vuint32m4_t indices_vec;
        vfloat32m4_t x_vec;
        vuint32m4_t idx_base;

        // Process in vector chunks
        for (Index_type i = 0; i < LEN_1D; ) {
            vl = __riscv_vsetvl_e32m4(LEN_1D - i);

            // Load x[i:i+vl]
            x_vec = __riscv_vle32_v_f32m4(&x[i], vl);

            // Create mask where x < 0.0
            mask = __riscv_vmflt_vf_f32m4_b32(x_vec, 0.0f, vl);

            // Generate index sequence: i, i+1, ..., i+vl-1
            idx_base = __riscv_vid_v_u32m4(vl);
            idx_base = __riscv_vadd_vx_u32m4(idx_base, i, vl);

            // Compress indices based on mask
            indices_vec = __riscv_vcompress_vm_u32m4(idx_base, mask, vl);

            // Store compressed indices to idx_list
            __riscv_vse32_v_u32m4(&idx_list[count], indices_vec, vl);

            // Count how many elements were selected
            count += __riscv_vpopc_m_b32(mask, vl);

            i += vl;
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            if (x[i] < 0.0) {
                idx_list[count++] = i;
            }
        }
#endif

        len = count;
        dummy(NULL, NULL, NULL, NULL, NULL, (real_t)count);
    }
    idx_list[0] = len;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

