real_t basic_init_view1d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t val = 1.0e-7;
    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        size_t len = LEN_1D;
        size_t i = 0;

        // We assume real_t is float for RVV intrinsics as it's the most common case.
        // If real_t is double, this would need adjustment to vfloat64m1_t and related intrinsics.
        // Using vsetvl_e32m1 implies 32-bit elements (float).

        while (i < len) {
            size_t vl = __riscv_vsetvl_e32m1(len - i);

            // Create index vector: 0, 1, ..., vl-1
            vuint32m1_t idx_vec = __riscv_vid(vl);
            // Add offset i to indices: i, i+1, ..., i+vl-1
            idx_vec = __riscv_vadd(idx_vec, i, vl);

            // Convert unsigned int to float
            vfloat32m1_t idx_float = __riscv_vfcvt_f_x_w(idx_vec, vl);

            // Multiply by val
            vfloat32m1_t result = __riscv_vfmul(idx_float, val, vl);

            // Store to array a
            __riscv_vseff(a + i, result, vl);

            i += vl;
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            a[i] = (real_t)(i + 1) * val;
        }
#endif
        dummy(a, NULL, NULL, NULL, NULL, val);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

