real_t basic_init_view1d_offset(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t val = 1.0e-7;
    Index_type ibegin = 1;

#if defined(__riscv_vector)
    size_t n_elements = LEN_1D - ibegin;
    if (n_elements > 0) {
        if (sizeof(real_t) == sizeof(float)) {
            size_t i = 0;
            while (i < n_elements) {
                size_t remaining = n_elements - i;
                size_t current_vl = __riscv_vsetvl_e32m1(remaining);

                // Generate index sequence: 0, 1, 2, ...
                vuint32m1_t idx_seq = __riscv_vid_v_u32m1(current_vl);

                // Add offset (ibegin + i) to get actual indices
                uint32_t offset = (uint32_t)(ibegin + i);
                vuint32m1_t idx_with_offset = __riscv_vadd_vx_u32m1(idx_seq, offset, current_vl);

                // Convert integer indices to float
                // Use the correct intrinsic name and ensure type compatibility
                vfloat32m1_t idx_float = __riscv_vfcvt_f_x_v_f32m1(idx_with_offset, current_vl);

                // Multiply by val
                vfloat32m1_t result = __riscv_vfmul_vf_f32m1(idx_float, val, current_vl);

                // Store result to a[i...i+current_vl-1]
                __riscv_vsegf8_f32m1(a + i, result, current_vl);

                i += current_vl;
            }
        } else if (sizeof(real_t) == sizeof(double)) {
            size_t i = 0;
            while (i < n_elements) {
                size_t remaining = n_elements - i;
                size_t current_vl = __riscv_vsetvl_e64m1(remaining);

                vuint64m1_t idx_seq = __riscv_vid_v_u64m1(current_vl);
                uint64_t offset = (uint64_t)(ibegin + i);
                vuint64m1_t idx_with_offset = __riscv_vadd_vx_u64m1(idx_seq, offset, current_vl);

                vfloat64m1_t idx_float = __riscv_vfcvt_f_x_v_f64m1(idx_with_offset, current_vl);
                vfloat64m1_t result = __riscv_vfmul_vf_f64m1(idx_float, val, current_vl);

                __riscv_vsegf8_f64m1(a + i, result, current_vl);

                i += current_vl;
            }
        } else {
            // Fallback for other types
            for (Index_type i = ibegin; i < LEN_1D; ++i) {
                a[i - ibegin] = (real_t)i * val;
            }
        }
    }
#else
    for (Index_type i = ibegin; i < LEN_1D; ++i) {
        a[i - ibegin] = (real_t)i * val;
    }
#endif

    dummy(a, NULL, NULL, NULL, NULL, val);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

