            vfloat32m1_t xv_sq = __riscv_vfmul(xv_minus_half, xv_minus_half, vl);

            // Add constant term: denom = (xv - 0.5)^2 + (ypoint - yp)^2
            vfloat32m1_t denom = __riscv_vfadd(xv_sq, yp_diff_sq, vl);

            // Add 1.0f inside sqrt: denom + 1.0f
            vfloat32m1_t denom_plus_one = __riscv_vfadd(denom, one, vl);

            // Sqrt
            vfloat32m1_t sqrt_val = __riscv_vsqrts(denom_plus_one, vl);

            // Reciprocal: 1.0f / sqrt_val
            vfloat32m1_t recip = __riscv_vfdiv(one, sqrt_val, vl);

            // Reduce sum
            sumx += __riscv_vfredosum(recip, vl);

            i += vl;
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t xv = x0 + i*h;
            real_t denom = (xv - 0.5)*(xv - 0.5) + yp_diff_sq;
            sumx += 1.0f / sqrtf(denom + 1.0f);
        }
#endif

        acc += sumx;
        dummy(NULL, NULL, NULL, NULL, NULL, sumx);
    }
    x[0] = acc / (real_t)(iterations * LEN_1D);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

