real_t lcals_diff_predict(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type offset = LEN_1D;

    for (int nl = 0; nl < iterations; nl++) {
        #if defined(__riscv_vector)
        // Vectorized loop for RISC-V
        size_t vl = __riscv_vsetvl_e32m1(LEN_1D);

        // Process in chunks of vector length
        for (Index_type i = 0; i < LEN_1D; i += vl) {
            size_t current_vl = __riscv_vsetvl_e32m1(LEN_1D - i);

            // Load cx[i + offset*4]
            vfloat32m1_t ar_vec = __riscv_vle32_v_f32m1(cx + i + offset * 4, current_vl);

            // Load px[i + offset*4]
            vfloat32m1_t px4_vec = __riscv_vle32_v_f32m1(px + i + offset * 4, current_vl);

            // br = ar - px4
            vfloat32m1_t br_vec = __riscv_vfsub_vv_f32m1(ar_vec, px4_vec, current_vl);

            // Store ar to px[i + offset*4]
            __riscv_vse32_v_f32m1(px + i + offset * 4, ar_vec, current_vl);

            // Load px[i + offset*5]
            vfloat32m1_t px5_vec = __riscv_vle32_v_f32m1(px + i + offset * 5, current_vl);

            // cr = br - px5
            vfloat32m1_t cr_vec = __riscv_vfsub_vv_f32m1(br_vec, px5_vec, current_vl);

            // Store br to px[i + offset*5]
            __riscv_vse32_v_f32m1(px + i + offset * 5, br_vec, current_vl);

            // Load px[i + offset*6]
            vfloat32m1_t px6_vec = __riscv_vle32_v_f32m1(px + i + offset * 6, current_vl);

            // ar_new = cr - px6
            vfloat32m1_t ar_new_vec = __riscv_vfsub_vv_f32m1(cr_vec, px6_vec, current_vl);

            // Store cr to px[i + offset*6]
            __riscv_vse32_v_f32m1(px + i + offset * 6, cr_vec, current_vl);

            // Load px[i + offset*7]
            vfloat32m1_t px7_vec = __riscv_vle32_v_f32m1(px + i + offset * 7, current_vl);

            // br_new = ar_new - px7
            vfloat32m1_t br_new_vec = __riscv_vfsub_vv_f32m1(ar_new_vec, px7_vec, current_vl);

            // Store ar_new to px[i + offset*7]
            __riscv_vse32_v_f32m1(px + i + offset * 7, ar_new_vec, current_vl);

            // Load px[i + offset*8]
            vfloat32m1_t px8_vec = __riscv_vle32_v_f32m1(px + i + offset * 8, current_vl);

            // cr_new = br_new - px8
            vfloat32m1_t cr_new_vec = __riscv_vfsub_vv_f32m1(br_new_vec, px8_vec, current_vl);

            // Store br_new to px[i + offset*8]
            __riscv_vse32_v_f32m1(px + i + offset * 8, br_new_vec, current_vl);

            // Load px[i + offset*9]
            vfloat32m1_t px9_vec = __riscv_vle32_v_f32m1(px + i + offset * 9, current_vl);

            // ar_new2 = cr_new - px9
            vfloat32m1_t ar_new2_vec = __riscv_vfsub_vv_f32m1(cr_new_vec, px9_vec, current_vl);

            // Store cr_new to px[i + offset*9]
            __riscv_vse32_v_f32m1(px + i + offset * 9, cr_new_vec, current_vl);

            // Load px[i + offset*10]
            vfloat32m1_t px10_vec = __riscv_vle32_v_f32m1(px + i + offset * 10, current_vl);

            // br_new2 = ar_new2 - px10
            vfloat32m1_t br_new2_vec = __riscv_vfsub_vv_f32m1(ar_new2_vec, px10_vec, current_vl);

            // Store ar_new2 to px[i + offset*10]
            __riscv_vse32_v_f32m1(px + i + offset * 10, ar_new2_vec, current_vl);

            // Load px[i + offset*11]
            vfloat32m1_t px11_vec = __riscv_vle32_v_f32m1(px + i + offset * 11, current_vl);

            // cr_new2 = br_new2 - px11
            vfloat32m1_t cr_new2_vec = __riscv_vfsub_vv_f32m1(br_new2_vec, px11_vec, current_vl);

            // Store br_new2 to px[i + offset*11]
            __riscv_vse32_v_f32m1(px + i + offset * 11, br_new2_vec, current_vl);

            // Load px[i + offset*12]
            vfloat32m1_t px12_vec = __riscv_vle32_v_f32m1(px + i + offset * 12, current_vl);

            // result = cr_new2 - px12
            vfloat32m1_t result_vec = __riscv_vfsub_vv_f32m1(cr_new2_vec, px12_vec, current_vl);

            // Store result to px[i + offset*13]
            __riscv_vse32_v_f32m1(px + i + offset * 13, result_vec, current_vl);

            // Store cr_new2 to px[i + offset*12]
            __riscv_vse32_v_f32m1(px + i + offset * 12, cr_new2_vec, current_vl);
        }
        #else
        // Scalar fallback for non-RISC-V or when vector is not available
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t ar = cx[i + offset * 4];
            real_t br = ar - px[i + offset * 4];
            px[i + offset * 4]  = ar;
            real_t cr = br - px[i + offset * 5];
            px[i + offset * 5]  = br;
            ar = cr - px[i + offset * 6];  px[i + offset * 6]  = cr;
            br = ar - px[i + offset * 7];  px[i + offset * 7]  = ar;
            cr = br - px[i + offset * 8];  px[i + offset * 8]  = br;
            ar = cr - px[i + offset * 9];  px[i + offset * 9]  = cr;
            br = ar - px[i + offset * 10]; px[i + offset * 10] = ar;
            cr = br - px[i + offset * 11]; px[i + offset * 11] = br;
            px[i + offset * 13] = cr - px[i + offset * 12];
            px[i + offset * 12] = cr;
        }
        #endif

        dummy(cx, px, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

