real_t lcals_first_diff(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
        #if defined(__riscv_vector)
        size_t len = LEN_1D - 1;

        // Use a loop that processes the array in vector chunks.
        // We use vsetvl_e32m1 to set the vector length based on remaining elements.
        // This ensures we handle any array size correctly without scalar fallback loops inside the hot path.
        size_t i = 0;
        while (i < len) {
            // Set VL to the minimum of max possible and remaining elements
            size_t vl = __riscv_vsetvl_e32m1(len - i);

            if (vl == 0) break;

            // Load y[i] ... y[i+vl-1]
            vfloat32m1_t y_curr = __riscv_vle32_v_f32m1(&y[i], vl);
            // Load y[i+1] ... y[i+vl]
            vfloat32m1_t y_next = __riscv_vle32_v_f32m1(&y[i+1], vl);

            // Compute x[i] = y[i+1] - y[i]
            vfloat32m1_t diff = __riscv_vfsub_vv_f32m1(y_next, y_curr, vl);

            // Store result to x[i] ... x[i+vl-1]
            __riscv_vse32_v_f32m1(&x[i], diff, vl);

            i += vl;
        }
        #else
        for (Index_type i = 0; i < LEN_1D - 1; ++i) {
            x[i] = y[i+1] - y[i];
        }
        #endif
        dummy(x, y, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

