real_t lcals_first_min(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type loc = 0;
    real_t mn = x[0];

    for (int nl = 0; nl < iterations; nl++) {
        loc = 0; 
        mn = x[0];

#if defined(__riscv_vector)
        // Assume real_t is float (32-bit) for vectorization. 
        // If real_t is double, this code would need adjustment to e64 intrinsics.
        // Given the context of such benchmarks, float is the standard assumption.

        Index_type i = 0;
        while (i < LEN_1D) {
            size_t vl = __riscv_vsetvl_e32m1(LEN_1D - i);

            // Load vector
            vfloat32m1_t vx = __riscv_vle32_v_f32m1(x + i, vl);

            // Compare: vx < mn (scalar broadcast)
            // Correct intrinsic name: __riscv_vmflt_vf_f32m1_b32
            vbool32_t mask = __riscv_vmflt_vf_f32m1_b32(vx, mn, vl);

            int first_idx = __riscv_vfirst(mask, vl);

            if (first_idx == -1) {
                // No element in this chunk is smaller than current mn
                i += vl;
            } else {
                // Found at least one element smaller
                Index_type new_loc = i + first_idx;
                real_t new_mn = x[new_loc];

                mn = new_mn;
                loc = new_loc;

                // Since mn has changed, we must check the rest of the current vector
                // against the NEW mn to ensure we find the true first minimum.
                // We do this with a scalar loop over the remainder of the vector.
                for (int j = first_idx + 1; j < vl; j++) {
                    if (x[i + j] < mn) {
                        mn = x[i + j];
                        loc = i + j;
                    }
                }

                i += vl;
            }
        }
#else
        // Fallback to scalar implementation if RVV is not available
        for (Index_type i = 0; i < LEN_1D; ++i) {
            if (x[i] < mn) { 
                mn = x[i]; 
                loc = i; 
            }
        }
#endif

        dummy(x, NULL, NULL, NULL, NULL, mn);
    }

    y[0] = mn;
    y[1] = (real_t)loc / (real_t)LEN_1D;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

