real_t lcals_first_sum(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
        #if defined(__riscv_vector)
        // Vectorized loop for the main computation
        // We process elements from index 1 to LEN_1D-1
        // x[i] = y[i-1] + y[i]

        size_t i = 1;
        size_t len = LEN_1D - 1; // Number of elements to process (from 1 to LEN_1D-1)

        if (len > 0) {
            vfloat32m1_t v_y_prev;
            vfloat32m1_t v_y_curr;

            // Process in chunks
            while (i < LEN_1D) {
                size_t remaining = LEN_1D - i;
                size_t vl = __riscv_vsetvl_e32m1(remaining);

                // Load y[i-1] ... y[i+vl-2]
                // This corresponds to indices [i-1, i+vl-2]
                v_y_prev = __riscv_vle32_vf(vl, &y[i-1]);

                // Load y[i] ... y[i+vl-1]
                // This corresponds to indices [i, i+vl-1]
                v_y_curr = __riscv_vle32_vf(vl, &y[i]);

                // Compute sum
                vfloat32m1_t v_x = __riscv_vadd_vv(v_y_prev, v_y_curr, vl);

                // Store result to x[i] ... x[i+vl-1]
                __riscv_vse32_vf(vl, v_x, &x[i]);

                i += vl;
            }
        }
        #else
        for (Index_type i = 1; i < LEN_1D; ++i) {
            x[i] = y[i-1] + y[i];
        }
        #endif

        dummy(x, y, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t lcals_gen_lin_recur(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type kb5i = 0;

    #if defined(__riscv_vector)
    // We must handle the case where LEN_1D might not be a multiple of VLEN.
    // Also, we need to ensure we are using the correct element type for real_t.
    // Assuming real_t is float (32-bit). If it's double, this needs vfloat64m1_t and e64.
    // Given the previous failure, it's likely due to tail handling or type mismatch.
    // Let's implement a robust loop that handles tails correctly.

    size_t len = LEN_1D;

    for (int nl = 0; nl < iterations / 16 + 1; nl++) {
        // First loop: k from 0 to LEN_1D - 1
        // Process in chunks if necessary, but __riscv_vsetvl_e32m1(len) should handle the full length
        // by setting vl to the minimum of len and VLEN, and the intrinsics handle the rest?
        // Actually, standard RVV intrinsics with a fixed vl only process 'vl' elements.
        // We need a loop to process all elements if len > VLEN.

        size_t offset = 0;
        while (offset < len) {
            size_t vl = __riscv_vsetvl_e32m1(len - offset);

            vfloat32m1_t v_sa = __riscv_vle32_v_f32m1((const float*)(sa + offset), vl);
            vfloat32m1_t v_stb5 = __riscv_vle32_v_f32m1((const float*)(stb5 + offset), vl);
            vfloat32m1_t v_sb = __riscv_vle32_v_f32m1((const float*)(sb + offset), vl);

            vfloat32m1_t v_prod = __riscv_vfmul_vv_f32m1(v_stb5, v_sb, vl);
            vfloat32m1_t v_b5 = __riscv_vfadd_vv_f32m1(v_sa, v_prod, vl);

            __riscv_vse32_v_f32m1((float*)(b5 + kb5i + offset), v_b5, vl);

            vfloat32m1_t v_new_stb5 = __riscv_vfsub_vv_f32m1(v_b5, v_stb5, vl);
            __riscv_vse32_v_f32m1((float*)(stb5 + offset), v_new_stb5, vl);

            offset += vl;
        }

        // Second loop: i from 1 to LEN_1D, k = LEN_1D - i
        // This iterates k from LEN_1D-1 down to 0.
        // Since operations are independent per index, order doesn't matter for correctness.
        // We can process forward again (0 to LEN_1D-1) as long as we use the updated values.
        // The scalar code does: for i=1..N, k=N-i. So k goes N-1, N-2, ..., 0.
        // Vectorizing forward (0..N-1) produces the same result because there are no dependencies between k indices.

        offset = 0;
        while (offset < len) {
            size_t vl = __riscv_vsetvl_e32m1(len - offset);

            vfloat32m1_t v_sa = __riscv_vle32_v_f32m1((const float*)(sa + offset), vl);
            vfloat32m1_t v_stb5 = __riscv_vle32_v_f32m1((const float*)(stb5 + offset), vl);
            vfloat32m1_t v_sb = __riscv_vle32_v_f32m1((const float*)(sb + offset), vl);

            vfloat32m1_t v_prod = __riscv_vfmul_vv_f32m1(v_stb5, v_sb, vl);
            vfloat32m1_t v_b5 = __riscv_vfadd_vv_f32m1(v_sa, v_prod, vl);

            __riscv_vse32_v_f32m1((float*)(b5 + kb5i + offset), v_b5, vl);

            vfloat32m1_t v_new_stb5 = __riscv_vfsub_vv_f32m1(v_b5, v_stb5, vl);
            __riscv_vse32_v_f32m1((float*)(stb5 + offset), v_new_stb5, vl);

            offset += vl;
        }

        dummy(b5, stb5, sa, sb, NULL, 0.0);
    }
    #else
    for (int nl = 0; nl < iterations / 16 + 1; nl++) {
        for (Index_type k = 0; k < LEN_1D; ++k) {
            b5[k+kb5i] = sa[k] + stb5[k]*sb[k];
            stb5[k] = b5[k+kb5i] - stb5[k];
        }
        for (Index_type i = 1; i < LEN_1D + 1; ++i) {
            Index_type k = LEN_1D - i;
            b5[k+kb5i] = sa[k] + stb5[k]*sb[k];
            stb5[k] = b5[k+kb5i] - stb5[k];
        }
        dummy(b5, stb5, sa, sb, NULL, 0.0);
    }
    #endif

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t lcals_hydro_1d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t q = 0.5, r = 0.25, t = 0.125;
    for (int nl = 0; nl < iterations; nl++) {
        #if defined(__riscv_vector)
        size_t len = LEN_1D - 12;
        // Determine vector length for float32 with LMUL=1
        size_t vl = __riscv_vsetvl_e32m1(len);

        // Load y[i]
        vfloat32m1_t vy = __riscv_vle32_vf(vl, &y[0]);

        // Load z[i+10] and z[i+11]
        vfloat32m1_t vz10 = __riscv_vle32_vf(vl, &z[10]);
        vfloat32m1_t vz11 = __riscv_vle32_vf(vl, &z[11]);

        // Compute r*z[i+10] + t*z[i+11]
        vfloat32m1_t term1 = __riscv_vfmul_vf(vz10, r, vl);
        vfloat32m1_t term2 = __riscv_vfmul_vf(vz11, t, vl);
        vfloat32m1_t sum_terms = __riscv_vfadd_vv(term1, term2, vl);

        // Multiply by y[i]
        vfloat32m1_t product = __riscv_vfmul_vv(vy, sum_terms, vl);

        // Add q
        vfloat32m1_t result = __riscv_vfadd_vf(product, q, vl);

        // Store to x[i]
        __riscv_vse32_vf(result, &x[0], vl);
        #else
        for (Index_type i = 0; i < LEN_1D - 12; ++i) {
            x[i] = q + y[i]*( r*z[i+10] + t*z[i+11] );
        }
        #endif
        dummy(x, y, z, NULL, NULL, q);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t lcals_hydro_2d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t s = 0.0001, t = 0.5;
    Index_type kn = LEN_2D, jn = LEN_2D;

    for (int nl = 0; nl < iterations / 32 + 1; nl++) {
        // First loop: compute za and zb
        for (Index_type k = 1; k < kn - 1; ++k) {
            #if defined(__riscv_vector)
            size_t vl = __riscv_vsetvl_e32m1(jn - 2);

            // Process in vector chunks
            for (Index_type j = 1; j < jn - 1; j += vl) {
                size_t actual_vl = __riscv_vsetvl_e32m1(jn - 1 - j);

                // Compute za[k][j]
                // Term1: (zp[k+1][j-1] + zq[k+1][j-1] - zp[k][j-1] - zq[k][j-1])
                vfloat32m1_t zp_k_plus_1_j_minus_1 = __riscv_vle32_vf(zp[k+1] + j - 1, actual_vl);
                vfloat32m1_t zq_k_plus_1_j_minus_1 = __riscv_vle32_vf(zq[k+1] + j - 1, actual_vl);
                vfloat32m1_t zp_k_j_minus_1 = __riscv_vle32_vf(zp[k] + j - 1, actual_vl);
                vfloat32m1_t zq_k_j_minus_1 = __riscv_vle32_vf(zq[k] + j - 1, actual_vl);

                vfloat32m1_t term1_num = __riscv_vfadd_vv(zp_k_plus_1_j_minus_1, zq_k_plus_1_j_minus_1, actual_vl);
                vfloat32m1_t term1_sub = __riscv_vfsub_vv(term1_num, zp_k_j_minus_1, actual_vl);
                vfloat32m1_t term1 = __riscv_vfsub_vv(term1_sub, zq_k_j_minus_1, actual_vl);

                // Term2: (zr[k][j] + zr[k][j-1])
                vfloat32m1_t zr_k_j = __riscv_vle32_vf(zr[k] + j, actual_vl);
                vfloat32m1_t zr_k_j_minus_1 = __riscv_vle32_vf(zr[k] + j - 1, actual_vl);
                vfloat32m1_t term2 = __riscv_vfadd_vv(zr_k_j, zr_k_j_minus_1, actual_vl);

                // Denom: (zm[k][j-1] + zm[k+1][j-1])
                vfloat32m1_t zm_k_j_minus_1 = __riscv_vle32_vf(zm[k] + j - 1, actual_vl);
                vfloat32m1_t zm_k_plus_1_j_minus_1 = __riscv_vle32_vf(zm[k+1] + j - 1, actual_vl);
                vfloat32m1_t denom = __riscv_vfadd_vv(zm_k_j_minus_1, zm_k_plus_1_j_minus_1, actual_vl);

                // Result: term1 * term2 / denom
                vfloat32m1_t num = __riscv_vfmul_vv(term1, term2, actual_vl);
                vfloat32m1_t za_val = __riscv_vfdiv_vv(num, denom, actual_vl);
                __riscv_vse32_vf(za[k] + j, za_val, actual_vl);

                // Compute zb[k][j]
                // Term1: (zp[k][j-1] + zq[k][j-1] - zp[k][j] - zq[k][j])
                vfloat32m1_t zp_k_j = __riscv_vle32_vf(zp[k] + j, actual_vl);
                vfloat32m1_t zq_k_j = __riscv_vle32_vf(zq[k] + j, actual_vl);

                vfloat32m1_t term1_b_num = __riscv_vfadd_vv(zp_k_j_minus_1, zq_k_j_minus_1, actual_vl);
                vfloat32m1_t term1_b_sub = __riscv_vfsub_vv(term1_b_num, zp_k_j, actual_vl);
                vfloat32m1_t term1_b = __riscv_vfsub_vv(term1_b_sub, zq_k_j, actual_vl);

                // Term2: (zr[k][j] + zr[k-1][j])
                vfloat32m1_t zr_k_minus_1_j = __riscv_vle32_vf(zr[k-1] + j, actual_vl);
                vfloat32m1_t term2_b = __riscv_vfadd_vv(zr_k_j, zr_k_minus_1_j, actual_vl);

                // Denom: (zm[k][j] + zm[k][j-1])
                vfloat32m1_t zm_k_j = __riscv_vle32_vf(zm[k] + j, actual_vl);
                vfloat32m1_t denom_b = __riscv_vfadd_vv(zm_k_j, zm_k_j_minus_1, actual_vl);

                // Result: term1_b * term2_b / denom_b
                vfloat32m1_t num_b = __riscv_vfmul_vv(term1_b, term2_b, actual_vl);
                vfloat32m1_t zb_val = __riscv_vfdiv_vv(num_b, denom_b, actual_vl);
                __riscv_vse32_vf(zb[k] + j, zb_val, actual_vl);
            }
            #else
            for (Index_type j = 1; j < jn - 1; ++j) {
                za[k][j] = ( zp[k+1][j-1] + zq[k+1][j-1] - zp[k][j-1] - zq[k][j-1] ) *
                           ( zr[k][j] + zr[k][j-1] ) / ( zm[k][j-1] + zm[k+1][j-1] );
                zb[k][j] = ( zp[k][j-1] + zq[k][j-1] - zp[k][j] - zq[k][j] ) *
                           ( zr[k][j] + zr[k-1][j] ) / ( zm[k][j] + zm[k][j-1] );
            }
            #endif
        }

        // Second loop: update zu and zv
        for (Index_type k = 1; k < kn - 1; ++k) {
            #if defined(__riscv_vector)
            size_t vl = __riscv_vsetvl_e32m1(jn - 2);

            for (Index_type j = 1; j < jn - 1; j += vl) {
                size_t actual_vl = __riscv_vsetvl_e32m1(jn - 1 - j);

                // Load values for zu update
                vfloat32m1_t za_j = __riscv_vle32_vf(za[k] + j, actual_vl);
                vfloat32m1_t za_j_minus_1 = __riscv_vle32_vf(za[k] + j - 1, actual_vl);
                vfloat32m1_t zb_j = __riscv_vle32_vf(zb[k] + j, actual_vl);
                vfloat32m1_t zb_j_plus_1 = __riscv_vle32_vf(zb[k+1] + j, actual_vl);

                vfloat32m1_t zz_j = __riscv_vle32_vf(zz[k] + j, actual_vl);
                vfloat32m1_t zz_j_plus_1 = __riscv_vle32_vf(zz[k] + j + 1, actual_vl);
                vfloat32m1_t zz_j_minus_1 = __riscv_vle32_vf(zz[k] + j - 1, actual_vl);
                vfloat32m1_t zz_k_minus_1_j = __riscv_vle32_vf(zz[k-1] + j, actual_vl);
                vfloat32m1_t zz_k_plus_1_j = __riscv_vle32_vf(zz[k+1] + j, actual_vl);

                // Compute terms for zu
                vfloat32m1_t diff_zz_1 = __riscv_vfsub_vv(zz_j, zz_j_plus_1, actual_vl);
                vfloat32m1_t diff_zz_2 = __riscv_vfsub_vv(zz_j, zz_j_minus_1, actual_vl);
                vfloat32m1_t diff_zz_3 = __riscv_vfsub_vv(zz_j, zz_k_minus_1_j, actual_vl);
                vfloat32m1_t diff_zz_4 = __riscv_vfsub_vv(zz_j, zz_k_plus_1_j, actual_vl);

                vfloat32m1_t term1 = __riscv_vfmul_vv(za_j, diff_zz_1, actual_vl);
                vfloat32m1_t term2 = __riscv_vfmul_vv(za_j_minus_1, diff_zz_2, actual_vl);
                vfloat32m1_t term3 = __riscv_vfmul_vv(zb_j, diff_zz_3, actual_vl);
                vfloat32m1_t term4 = __riscv_vfmul_vv(zb_j_plus_1, diff_zz_4, actual_vl);

                vfloat32m1_t sum1 = __riscv_vfsub_vv(term1, term2, actual_vl);
                vfloat32m1_t sum2 = __riscv_vfsub_vv(sum1, term3, actual_vl);
                vfloat32m1_t sum_final = __riscv_vfadd_vv(sum2, term4, actual_vl);

                vfloat32m1_t scaled = __riscv_vfmul_vs(sum_final, s, actual_vl);
                vfloat32m1_t zu_old = __riscv_vle32_vf(zu[k] + j, actual_vl);
                vfloat32m1_t zu_new = __riscv_vfadd_vv(zu_old, scaled, actual_vl);
                __riscv_vse32_vf(zu[k] + j, zu_new, actual_vl);

                // Load values for zv update
                vfloat32m1_t zr_j = __riscv_vle32_vf(zr[k] + j, actual_vl);
                vfloat32m1_t zr_j_plus_1 = __riscv_vle32_vf(zr[k] + j + 1, actual_vl);
                vfloat32m1_t zr_j_minus_1 = __riscv_vle32_vf(zr[k] + j - 1, actual_vl);
                vfloat32m1_t zr_k_minus_1_j = __riscv_vle32_vf(zr[k-1] + j, actual_vl);
                vfloat32m1_t zr_k_plus_1_j = __riscv_vle32_vf(zr[k+1] + j, actual_vl);

                // Compute terms for zv
                vfloat32m1_t diff_zr_1 = __riscv_vfsub_vv(zr_j, zr_j_plus_1, actual_vl);
                vfloat32m1_t diff_zr_2 = __riscv_vfsub_vv(zr_j, zr_j_minus_1, actual_vl);
                vfloat32m1_t diff_zr_3 = __riscv_vfsub_vv(zr_j, zr_k_minus_1_j, actual_vl);
                vfloat32m1_t diff_zr_4 = __riscv_vfsub_vv(zr_j, zr_k_plus_1_j, actual_vl);

                vfloat32m1_t term1_v = __riscv_vfmul_vv(za_j, diff_zr_1, actual_vl);
                vfloat32m1_t term2_v = __riscv_vfmul_vv(za_j_minus_1, diff_zr_2, actual_vl);
                vfloat32m1_t term3_v = __riscv_vfmul_vv(zb_j, diff_zr_3, actual_vl);
                vfloat32m1_t term4_v = __riscv_vfmul_vv(zb_j_plus_1, diff_zr_4, actual_vl);

                vfloat32m1_t sum1_v = __riscv_vfsub_vv(term1_v, term2_v, actual_vl);
                vfloat32m1_t sum2_v = __riscv_vfsub_vv(sum1_v, term3_v, actual_vl);
                vfloat32m1_t sum_final_v = __riscv_vfadd_vv(sum2_v, term4_v, actual_vl);

                vfloat32m1_t scaled_v = __riscv_vfmul_vs(sum_final_v, s, actual_vl);
                vfloat32m1_t zv_old = __riscv_vle32_vf(zv[k] + j, actual_vl);
                vfloat32m1_t zv_new = __riscv_vfadd_vv(zv_old, scaled_v, actual_vl);
                __riscv_vse32_vf(zv[k] + j, zv_new, actual_vl);
            }
            #else
            for (Index_type j = 1; j < jn - 1; ++j) {
                zu[k][j] += s*( za[k][j]   * ( zz[k][j] - zz[k][j+1] ) -
                                za[k][j-1] * ( zz[k][j] - zz[k][j-1] ) -
                                zb[k][j]   * ( zz[k][j] - zz[k-1][j] ) +
                                zb[k+1][j] * ( zz[k][j] - zz[k+1][j] ) );
                zv[k][j] += s*( za[k][j]   * ( zr[k][j] - zr[k][j+1] ) -
                                za[k][j-1] * ( zr[k][j] - zr[k][j-1] ) -
                                zb[k][j]   * ( zr[k][j] - zr[k-1][j] ) +
                                zb[k+1][j] * ( zr[k][j] - zr[k+1][j] ) );
            }
            #endif
        }

        // Third loop: compute output arrays
        for (Index_type k = 1; k < kn - 1; ++k) {
            #if defined(__riscv_vector)
            size_t vl = __riscv_vsetvl_e32m1(jn - 2);

            for (Index_type j = 1; j < jn - 1; j += vl) {
                size_t actual_vl = __riscv_vsetvl_e32m1(jn - 1 - j);

                vfloat32m1_t zr_j = __riscv_vle32_vf(zr[k] + j, actual_vl);
                vfloat32m1_t zu_j = __riscv_vle32_vf(zu[k] + j, actual_vl);
                vfloat32m1_t zrout_val = __riscv_vfmadd_vs(zu_j, t, zr_j, actual_vl);
                __riscv_vse32_vf(zrout[k] + j, zrout_val, actual_vl);

                vfloat32m1_t zz_j = __riscv_vle32_vf(zz[k] + j, actual_vl);
                vfloat32m1_t zv_j = __riscv_vle32_vf(zv[k] + j, actual_vl);
                vfloat32m1_t zzout_val = __riscv_vfmadd_vs(zv_j, t, zz_j, actual_vl);
                __riscv_vse32_vf(zzout[k] + j, zzout_val, actual_vl);
            }
            #else
            for (Index_type j = 1; j < jn - 1; ++j) {
                zrout[k][j] = zr[k][j] + t*zu[k][j];
                zzout[k][j] = zz[k][j] + t*zv[k][j];
            }
            #endif
        }

        dummy(NULL, NULL, NULL, NULL, NULL, t);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t lcals_int_predict(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type offset = LEN_1D;
    real_t dm22 = 0.7, dm23 = 0.6, dm24 = 0.5, dm25 = 0.4;
    real_t dm26 = 0.3, dm27 = 0.2, dm28 = 0.1, c0 = 1.0/3.0;

    for (int nl = 0; nl < iterations; nl++) {
        #if defined(__riscv_vector)
        // Calculate base pointers for each offset
        real_t *p12 = &px[offset * 12];
        real_t *p11 = &px[offset * 11];
        real_t *p10 = &px[offset * 10];
        real_t *p9  = &px[offset * 9];
        real_t *p8  = &px[offset * 8];
        real_t *p7  = &px[offset * 7];
        real_t *p6  = &px[offset * 6];
        real_t *p5  = &px[offset * 5];
        real_t *p4  = &px[offset * 4];
        real_t *p2  = &px[offset * 2];

        size_t vl = __riscv_vsetvl_e32m1(LEN_1D);

        for (Index_type i = 0; i < LEN_1D; i += vl) {
            size_t actual_vl = __riscv_vsetvl_e32m1(LEN_1D - i);

            vfloat32m1_t v_p12 = __riscv_vle32_v_f32m1(p12 + i, actual_vl);
            vfloat32m1_t v_p11 = __riscv_vle32_v_f32m1(p11 + i, actual_vl);
            vfloat32m1_t v_p10 = __riscv_vle32_v_f32m1(p10 + i, actual_vl);
            vfloat32m1_t v_p9  = __riscv_vle32_v_f32m1(p9  + i, actual_vl);
            vfloat32m1_t v_p8  = __riscv_vle32_v_f32m1(p8  + i, actual_vl);
            vfloat32m1_t v_p7  = __riscv_vle32_v_f32m1(p7  + i, actual_vl);
            vfloat32m1_t v_p6  = __riscv_vle32_v_f32m1(p6  + i, actual_vl);
            vfloat32m1_t v_p5  = __riscv_vle32_v_f32m1(p5  + i, actual_vl);
            vfloat32m1_t v_p4  = __riscv_vle32_v_f32m1(p4  + i, actual_vl);
            vfloat32m1_t v_p2  = __riscv_vle32_v_f32m1(p2  + i, actual_vl);

            // Compute: dm28*p12 + dm27*p11 + ... + p2
            // Using vfmerge.vf to initialize with scalar multiplication if needed, 
            // but here we start with a multiply.
