        vfloat32m1_t vone = __riscv_vfmv_v_f32_f32(1.0f, vl);
        vfloat32m1_t vdenom = __riscv_vfsub_vv_f32(vexp_y, vone, vl);

        // Compute w[i] = x[i] / (expf(y[i]) - 1.0f)
        vfloat32m1_t vw = __riscv_vfdiv_vv_f32(vx, vdenom, vl);

        // Store w
