real_t lcals_tridiag_elim(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
        #if defined(__riscv_vector)
        // Loop range: i from 1 to LEN_1D-1. Total elements = LEN_1D - 1.
        size_t total_elements = LEN_1D - 1;

        if (total_elements > 0) {
            // Use vsetvl_e32m1 to ensure compatibility and correct VL calculation
            // We process the loop in chunks.
            size_t i = 1;

            while (i < LEN_1D) {
                size_t remaining = LEN_1D - i;
                size_t vl = __riscv_vsetvl_e32m1(remaining);

                // Load z[i]...z[i+vl-1]
                vfloat32m1_t vz = __riscv_vle32_v_f32m1(&z[i], vl);

                // Load y[i]...y[i+vl-1]
                vfloat32m1_t vy = __riscv_vle32_v_f32m1(&y[i], vl);

                // Load xin[i-1]...xin[i+vl-2]
                // Since i starts at 1, xin index is i-1.
                vfloat32m1_t vxin = __riscv_vle32_v_f32m1(&xin[i-1], vl);

                // Compute: temp = y - xin
                vfloat32m1_t vtemp = __riscv_vfsub_vv_f32m1(vy, vxin, vl);

                // Compute: xout = z * temp
                vfloat32m1_t vxout = __riscv_vfmul_vv_f32m1(vz, vtemp, vl);

                // Store result
                __riscv_vse32_v_f32m1(&xout[i], vxout, vl);

                i += vl;
            }
        }
        #else
        for (Index_type i = 1; i < LEN_1D; ++i) {
            xout[i] = z[i] * ( y[i] - xin[i-1] );
        }
        #endif

        dummy(xout, xin, y, z, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

